    (m mx : mem) (tmp gap : list cell) (hj hk sh8 : list byte) (bflag bown : byte),
  rw_cells asegs mx spa tmp -> Z.of_nat (cells_size tmp) = 56 -> lo <= spa ->
  rw_cells asegs mx (spa + 56) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -160 - spa -> spa + 56 <= bv_unsigned sp + -104 ->
  rw_cells asegs mx (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells asegs mx ff [CB 32 hj; C8 (Z_to_bv 64 M); C1 bown; CB 15 hk; C8 (Z_to_bv 64 fp)] ->
  rw_cells asegs mx (Z.shiftr ff 3 + 2147450880) [CB 8 sh8] ->
  rw_cells asegs mx fp [C1 bflag] ->
  stk asegs mx lo spa -> mem_inv asegs mx ->
  as_RFS H ((0, ff, fp) :: LF) mx -> fresh_frame H LF 0 ff fp -> ACONST mx -> stack0 mx lo shi ->
  as_RFS H LF m ->
  munch (rs_W H lo sp stb ec tgt tn ff fp) m mx -> wmono asegs m mx ->
  AStateBlock LB mx stb ioc implb (rs_state S ds tn) (skipn (Z.to_nat (rs_take ds tn)) ds) -> fsobj H LF stb SZ_SPCI_STATE -> aapp stb SZ_SPCI_STATE ->
  (st_fb (rs_state S ds tn) <> FB_empty -> fsobj H LF (fb_begin (st_fb (rs_state S ds tn))) (fb_cap (st_fb (rs_state S ds tn)))) ->
  rw_cells asegs mx tgt [CB (Z.to_nat (rs_take ds tn)) (firstn (Z.to_nat (rs_take ds tn)) ds);
                         CB (Z.to_nat (tn - rs_take ds tn)) (skipn (Z.to_nat (rs_take ds tn)) junk)] ->
  aapp tgt tn -> fsobj H LF tgt tn -> accessible mx tgt tn -> 1 <= tn < 2^40 ->
  rw_cells asegs mx ec (ErrCodeCells (if zlength ds =? 0 then EC_ts_eof_a else E)) -> aapp ec 24 -> fsobj H LF ec 24 ->
  AXStatics2 mx -> AMiscVt48 mx ->
  0 <= rs_take ds tn <= tn -> k = rs_take ds tn ->
  aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt asegs (readsome_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB LF stb ioc implb tgt tn ec lo shi S ds junk E m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) xs3 xs4 (Z_to_bv 64 k) xs6 xs7 xs8 (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) xs11 t3' t4' t5' t6')
        F (Z_to_bv 64 ARS_EXIT) fc None mx (seg_rom asegs)).
