Lemma AFlatBuf_fs0 : forall ff fp LF m0 m1 m2 LB a F ds W,
  as_RFS H LF m0 -> fresh_frame H LF 0 ff fp ->
  AFlatBuf LB m1 a F ds -> (F <> FB_empty -> fsobj H LF (fb_begin F) (fb_cap F)) ->
  munch W m1 m2 -> wmono asegs m1 m2 -> Forall (win_fs0 ff) W ->
  disjoint_from W a SZ_FB -> (F <> FB_empty -> disjoint_from W (fb_begin F) (fb_cap F)) ->
  AFlatBuf LB m2 a F ds.
Proof.
  intros ff fp LF m0 m1 m2 LB a F ds W RF FF FB FOF MU WM FW D DB.
  pose proof (ff_facts _ _ _ _ _ FF) as (_ & _ & _ & _ & F1 & F2 & F3 & _ & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SHFF & _).
  eapply AFlatBuf_transport; [exact FB| exact MU| exact WM| exact D| exact DB|].
  intros NE. destruct FB as (_ & FOK & _). destruct FOK as [E|(q & INq & RBq & CAP & _)]; [contradiction|].
  pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6). pose proof RBq as (_ & _ & _ & APq & _).
  pose proof (fsobj_windows _ HH _ _ _ _ _ _ _ RF (FOF NE) FF C1 ltac:(lia) C3) as (_ & E2 & _). change (fshn 0) with 8 in E2. rewrite <- SHFF in E2.
  pose proof (sh_ge_lowsh (fb_begin F) C1) as KL. pose proof (sh_nsh_high (fb_begin F) (fb_cap F) C1 ltac:(lia) C3) as KH.
  clear - FW E2 KL KH. induction W as [|[l h] W IH]; [exact I|]. cbn [disjoint_from fst snd]. split; [| exact (IH (Forall_inv_tail FW))].
  pose proof (Forall_inv FW) as K. unfold win_fs0 in K. cbn [fst snd] in K. destruct K as [K|[K|[-> ->]]]; lia.
Qed.

